files.videos/ch-011/src/narration.json:
{
  "well": [
    {"text": "Sena reached the last well before the salt at first light."},
    {"text": "The keeper had already drawn the rope up and coiled it on the stone."},
    {"text": "\"Guild water is paid at the gate,\" he said. \"Not here.\""},
    {"text": "She showed him the courier's knot on her sleeve."},
    {"text": "He looked at it for as long as it took a mule to drink, then let the rope down again."}
  ],
  "salt": [
    {"text": "By noon the salt had begun to sing under her boots."},
    {"text": "She kept the sealed letter flat against her ribs and did not look back at the well."}
  ]
}
